export const getExportDocumentUrl = (id: number,) => {




  return `/api/documents/${id}/export`
}

/**
 * Accepts an optional `?format=docx|pdf` query parameter (default docx). It is documented here rather than declared as a parameter because orval would then emit an `ExportDocumentParams` symbol in both the zod and the types output, which collide under this package's `export *` index. PDF conversion requires LibreOffice on the server.
 * @summary Export the formatted document as a downloadable file
 */
export const exportDocument = async (id: number, options?: Parameters<typeof customFetch>[1]): Promise<Blob> => {

  return customFetch<Blob>(getExportDocumentUrl(id),
  {
    ...options,
    method: 'GET'


  }
);}





export const getExportDocumentQueryKey = (id: number,) => {
    return [
    `/api/documents/${id}/export`
    ] as const;
    }


export const getExportDocumentQueryOptions = <TData = Awaited<ReturnType<typeof exportDocument>>, TError = ErrorType<ErrorResponse>>(id: number, options?: { query?:UseQueryOptions<Awaited<ReturnType<typeof exportDocument>>, TError, TData>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getExportDocumentQueryKey(id);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof exportDocument>>> = ({ signal }) => exportDocument(id, { signal, ...requestOptions });





   return  { queryKey, queryFn, enabled: id !== null && id !== undefined, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof exportDocument>>, TError, TData> & { queryKey: QueryKey }
}

